// --runtime selects a proxy-kernel payload atop the chosen model
// (ROADMAP_LINUX_RUNTIME.md). Only "linux" exists, and only --mode fast
// and hybrid are wired (U2, U9) -- cycle has no roadmap need for it.
if (!cli.runtime.empty() && cli.runtime != "linux") {
  std::fprintf(stderr, "andesim run: unknown --runtime '%s' (want 'linux')\n",
               cli.runtime.c_str());
  return 2;
}
if (!cli.runtime.empty() && cli.model != "fast" && cli.model != "hybrid") {
  std::fprintf(stderr,
               "andesim run: --runtime linux is supported only with "
               "--mode fast or hybrid (not cycle)\n");
  return 2;
}
if (!cli.gdb_port.empty() && !cli.gdb) {
  std::fprintf(stderr, "andesim run: --gdb-port requires --gdb\n");
  return 2;
}
